import{_ as i,c as a,o as r,a9 as o}from"./chunks/framework.C3PHgg-M.js";const p=JSON.parse('{"title":"From Zero to Production","description":"A pragmatic end-to-end path from first service to production-ready PURISTA deployment","frontmatter":{"title":"From Zero to Production","description":"A pragmatic end-to-end path from first service to production-ready PURISTA deployment","order":50000},"headers":[],"relativePath":"handbook/from-zero-to-production.md","filePath":"handbook/from-zero-to-production.md","lastUpdated":1778094759000}'),t={name:"handbook/from-zero-to-production.md"};function l(n,e,s,d,c,u){return r(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="from-zero-to-production" tabindex="-1">From Zero to Production <a class="header-anchor" href="#from-zero-to-production" aria-label="Permalink to “From Zero to Production”">​</a></h1><p>This page is a practical implementation path to build and ship a PURISTA application.</p><h2 id="phase-1-foundation" tabindex="-1">Phase 1: Foundation <a class="header-anchor" href="#phase-1-foundation" aria-label="Permalink to “Phase 1: Foundation”">​</a></h2><ol><li>Create project and run quickstart flow.</li><li>Create first service plus at least one command, subscription, stream, and, if you need pull-based async work, a queue + worker pair.</li><li>Add schema validation for payload/parameter/output.</li><li>Add unit tests for service/command/subscription/stream.</li></ol><p>Reference:</p><ul><li><a href="./1_quickstart/">Quickstart</a></li><li><a href="./2_building_business-logic/service/">Service</a></li><li><a href="./2_building_business-logic/command/">Command</a></li><li><a href="./2_building_business-logic/stream/">Stream</a></li><li><a href="./2_building_business-logic/subscription/">Subscription</a></li><li><a href="./2_building_business-logic/queue/">Queues</a></li></ul><h2 id="phase-2-integration-ready-logic" tabindex="-1">Phase 2: Integration-ready logic <a class="header-anchor" href="#phase-2-integration-ready-logic" aria-label="Permalink to “Phase 2: Integration-ready logic”">​</a></h2><ol><li>Add stores (config/secret/state) where required.</li><li>Define resources (DB clients, external SDK wrappers).</li><li>Expose required commands/streams through REST endpoints (JSON + SSE).</li><li>Add invoke relations (<code>canInvoke</code>) explicitly.</li></ol><p>Reference:</p><ul><li><a href="./2_building_business-logic/stores/">Stores</a></li><li><a href="./2_building_business-logic/service/define-resources.html">Define resources</a></li><li><a href="./2_building_business-logic/exposing_endpoints/">Exposing commands</a></li></ul><h2 id="phase-3-runtime-architecture" tabindex="-1">Phase 3: Runtime architecture <a class="header-anchor" href="#phase-3-runtime-architecture" aria-label="Permalink to “Phase 3: Runtime architecture”">​</a></h2><ol><li>Choose event bridge based on delivery requirements.</li><li>Choose queue bridge (default in-memory vs Redis or other providers) for pull-based workloads.</li><li>Choose deployment model (monolith, microservice style, edge, serverless).</li><li>Configure graceful shutdown and startup ordering.</li></ol><p>Reference:</p><ul><li><a href="./3_eco_system/eventbridges/">Event bridges</a></li><li><a href="./3_eco_system/queue_bridges/">Queue bridges</a></li><li><a href="./5_deploy_and_scale/">Deploy &amp; Scale</a></li></ul><h2 id="phase-4-production-readiness" tabindex="-1">Phase 4: Production readiness <a class="header-anchor" href="#phase-4-production-readiness" aria-label="Permalink to “Phase 4: Production readiness”">​</a></h2><ol><li>Enable tracing and metrics with OpenTelemetry.</li><li>Add endpoint protection/auth middleware.</li><li>Validate error handling, timeout behavior, and stream cancellation behavior.</li><li>Run integration tests against real broker/store setup (including delivery semantics).</li><li>Verify stream consumers and telemetry in staging before rollout.</li></ol><p>Reference:</p><ul><li><a href="./4_open_telemetry/">OpenTelemetry</a></li><li><a href="./2_building_business-logic/error-handling.html">Error handling</a></li></ul><h2 id="release-checklist" tabindex="-1">Release checklist <a class="header-anchor" href="#release-checklist" aria-label="Permalink to “Release checklist”">​</a></h2><ul><li>schemas are explicit and stable</li><li>no accidental <code>any</code>/<code>unknown</code> in core paths</li><li>tests cover happy path, failure path, and cancellation/retry paths</li><li>streaming and event-bridge docs match implemented behavior</li><li>runtime config is documented</li><li>observability and shutdown behavior verified</li></ul>',20)])])}const m=i(t,[["render",l]]);export{p as __pageData,m as default};
